"""Full AttnRes + Canon-A/B/C/D with hashed n-gram input embeddings (over-encoded inputs).

Trunk: Full Attention Residuals (every sublayer reads a softmax mixture over the embedding and every earlier
block output, through one zero-initialized pseudo-query per sublayer) with Canon layers on every sublayer input
(A/C), on q, k, v (B) and on the MLP hidden (D), as in `attnres_full_canon_abcd`.

Addition: the input embedding is the token embedding plus hashed 2/3-gram embeddings (multi-head hashing). Lookups
cost no matrix arithmetic, so the memory adds capacity at essentially unchanged training FLOPs. The n-gram tables
live inside `transformer.wte`, so they train in the token-embedding AdamW group, and start at zero, so the model
starts exactly as the trunk without them.
"""
import torch
from torch import nn

from nexttransformer.models.backbone import norm
from nexttransformer.models.lm import ReferenceLM
from nexttransformer.models.residual import depth_attention

from .canon import Canon, CanonAttention, CanonMLP
from .ngram import NgramEmbedding


def _drawn_by_init_weights():
    """Stands in for nn.Embedding.reset_parameters: init_weights and init() own every embedding."""


class NgramCanonAttnRes(ReferenceLM):
    def __init__(self, config):
        super().__init__(config)
        self.depth_queries = nn.Parameter(torch.empty(2 * config.n_layer + 1, config.width))
        self.canon = nn.ModuleList(Canon(config.width) for _ in range(2 * config.n_layer))
        old = self.transformer.wte
        self.transformer.wte = NgramEmbedding(old.num_embeddings, config.width, config.option("ngram_orders"),
                                              config.option("ngram_rows"), config.option("ngram_heads"))
        # Keep the random sequence of the built-in build: no extra draws for embeddings in build_model.
        for module in self.modules():
            if isinstance(module, nn.Embedding):
                module.reset_parameters = _drawn_by_init_weights

    def _ordinary_hidden(self, idx):
        c = self.config
        x = self._embed_reference(idx)
        blocks, keys, partial = [], [], x
        for k in range(2 * c.n_layer):
            key = norm(partial)
            h = depth_attention(self.depth_queries[k], blocks + [partial], keys + [key])
            self._record("depth_read", sublayer=k, sources=len(blocks) + 1, tokens=idx.numel())
            if k % 2 == 0:
                blocks.append(partial); keys.append(key); partial = None
            h = self.canon[k](h)
            out = self._attention_branch(h, idx, k // 2) if k % 2 == 0 else self.transformer.h[k // 2].mlp(norm(h))
            partial = out if partial is None else partial + out
        h = depth_attention(self.depth_queries[-1], blocks + [partial], keys + [norm(partial)])
        self._record("depth_read", sublayer=2 * c.n_layer, sources=len(blocks) + 1, tokens=idx.numel())
        return h, None


def mixer(config, layer):
    return CanonAttention(config, layer)


def ffn(config, layer):
    return CanonMLP(config)


model = NgramCanonAttnRes
frozen = ("resid_lambdas", "x0_lambdas", "backout_lambda")


@torch.no_grad()
def init(model):
    """Canon layers start as the identity and n-gram tables at zero; depth queries are zeroed by ReferenceLM."""
    for module in model.modules():
        if isinstance(module, Canon):
            nn.init.zeros_(module.weight)
    std = model.config.option("ngram_init_std")
    for table in model.transformer.wte.tables:
        if std > 0:
            nn.init.normal_(table.weight, std=std)
        else:
            nn.init.zeros_(table.weight)


def check(config):
    orders, rows, heads = (config.option(k) for k in ("ngram_orders", "ngram_rows", "ngram_heads"))
    integer = lambda v: isinstance(v, int) and not isinstance(v, bool)
    if not (isinstance(orders, (list, tuple)) and all(integer(n) and 2 <= n <= 4 for n in orders)):
        raise ValueError("ngram_orders must be a list of orders from 2 to 4")
    if not (isinstance(rows, (list, tuple)) and len(rows) == len(orders) and all(integer(r) and r > 0 for r in rows)):
        raise ValueError("ngram_rows needs one positive table size per order")
    if not (integer(heads) and heads >= 1 and config.width % heads == 0):
        raise ValueError("ngram_heads must divide the width")
    std = config.option("ngram_init_std")
    if not (isinstance(std, (int, float)) and not isinstance(std, bool) and std >= 0):
        raise ValueError("ngram_init_std must be nonnegative")

